-- 11_  ÖTP VERİ TAŞIMA
--
-- Yereldeki JSON dosyalarından üretildi. Orijinal dosyalara
-- DOKUNULMADI; yalnızca okundu.
--
-- Üretim: 2026-08-27 14:27
-- Toplam: 214 ödeme · 62 kredi · 1270 taksit
--
-- Önce 10_otp.sql çalıştırılmalı (tablolar ve firmalar).
--
-- Tekrar çalıştırılabilir: kimlikler dosyada sabit, her insert
-- "on conflict do nothing". İkinci çalıştırma yeni satır açmaz.
-- ============================================================

begin;

-- ============ SQUALA · 36 ödeme · 5 kredi · 120 taksit ============

do $tasima$
declare v_firma uuid;
begin
  select id into v_firma from panel.firmalar where kisa_ad = 'squala';
  if v_firma is null then
    raise exception 'Firma bulunamadi: squala — once 10_otp.sql calistirilmali';
  end if;

  on conflict (id) do nothing;

  on conflict (id) do nothing;

  on conflict (kredi_id, no) do nothing;
end
$tasima$;

-- ============ WELLMOP · 178 ödeme · 57 kredi · 1150 taksit ============

do $tasima$
declare v_firma uuid;
begin
  select id into v_firma from panel.firmalar where kisa_ad = 'wellmop';
  if v_firma is null then
    raise exception 'Firma bulunamadi: wellmop — once 10_otp.sql calistirilmali';
  end if;

  on conflict (id) do nothing;

  on conflict (id) do nothing;

  on conflict (kredi_id, no) do nothing;

  on conflict (kredi_id, no) do nothing;

  on conflict (kredi_id, no) do nothing;
end
$tasima$;

commit;


-- ---------- Doğrulama ----------
-- Beklenen toplam: 214 ödeme · 62 kredi · 1270 taksit

select f.kisa_ad,
       (select count(*) from panel.otp_odemeler  o where o.firma_id = f.id) as odeme,
       (select count(*) from panel.otp_krediler  k where k.firma_id = f.id) as kredi,
       (select count(*) from panel.otp_taksitler t where t.firma_id = f.id) as taksit
  from panel.firmalar f
 where f.kisa_ad in ('squala','wellmop')
 order by f.kisa_ad;
